    [InlineData(0, 4, 1, 0, 90, 0, 4, 1)]    // 20×4 + 10×1
    [InlineData(2, 2, 1, 0, 150, 2, 2, 1)]   // 50×2 + 20×2 + 10×1
    [InlineData(1, 5, 5, 0, 150, 1, 5, 0)]
